package com.aoo.bcg.common.cache;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.Map;import java.util.Objects;import java.util.function.Function;
/** Reads only the envelope version before selecting a schema-specific payload decoder. */
public final class VersionedCacheCodec<T>{private final ObjectMapper mapper;private final Map<Integer,Function<JsonNode,T>>decoders;public VersionedCacheCodec(ObjectMapper mapper,Map<Integer,Function<JsonNode,T>>decoders){this.mapper=Objects.requireNonNull(mapper);this.decoders=Map.copyOf(decoders);if(this.decoders.isEmpty()||this.decoders.keySet().stream().anyMatch(v->v<=0))throw new IllegalArgumentException("supported cache schemas required");}public T decode(String json){try{JsonNode envelope=mapper.readTree(json);if(envelope==null||!envelope.isObject())throw new IllegalArgumentException("cache envelope must be an object");JsonNode versionNode=envelope.get("schemaVersion");if(versionNode==null||!versionNode.canConvertToInt())throw new IllegalArgumentException("cache schemaVersion missing");int version=versionNode.intValue();Function<JsonNode,T>decoder=decoders.get(version);if(decoder==null)throw new IllegalStateException("unsupported cache schemaVersion: "+version);JsonNode payload=envelope.get("payload");if(payload==null||payload.isNull())throw new IllegalArgumentException("cache payload missing");return Objects.requireNonNull(decoder.apply(payload),"cache decoder returned null");}catch(com.fasterxml.jackson.core.JsonProcessingException error){throw new IllegalArgumentException("invalid cache envelope",error);}}public String encode(int schemaVersion,T value){if(!decoders.containsKey(schemaVersion))throw new IllegalArgumentException("unsupported cache schemaVersion");try{return mapper.writeValueAsString(Map.of("schemaVersion",schemaVersion,"payload",value));}catch(com.fasterxml.jackson.core.JsonProcessingException error){throw new IllegalArgumentException("cannot encode cache value",error);}}}
